// Adopt a static disclosure without replacing its focused summary or changing
// its current open state. The markup argument must be a static component shell.
export function renderDisclosureShell(host, binding, markup) {
  const details = host.querySelector(`[data-bind="${binding}"]`);
  if (!details?.hasAttribute('data-lazy-disclosure')) {
    host.innerHTML = markup;
    return;
  }
  const template = document.createElement('template');
  template.innerHTML = markup;
  const rendered = template.content.querySelector(`[data-bind="${binding}"]`);
  const summary = details.querySelector('summary');
  for (const child of [...details.children]) {
    if (child !== summary) child.remove();
  }
  for (const child of [...rendered.children]) {
    if (child.tagName !== 'SUMMARY') details.appendChild(child);
  }
  details.removeAttribute('data-lazy-disclosure');
}
